// Every prop is authored once. Exterior and independent interior reuse these factories.
export const palette={wood:'#b8854f',edge:'#7d593b',lightWood:'#cfaa74',panel:'#c5a079',cream:'#efdfbd',blue:'#4f83ab',red:'#bf6558',floor:'#aaa4ba',iron:'#6c6b61'};
const candyColors=['#e8c463','#c7656c','#81ae87','#e5dab9','#8b97bf','#d18c54'];
export function makeProps(w){
 const {group,box,cyl,ball,beam,ring,mesh,face,label,batch,glass,THREE}=w,P=palette;
 function bottle(x,y,z,color,p){cyl(.065,.073,.21,x,y+.105,z,color,p,12);cyl(.031,.05,.055,x,y+.235,z,color,p,10);cyl(.04,.04,.026,x,y+.27,z,'#eee6cc',p,12);box(.118,.078,.006,x,y+.12,z+.072,'#f2e8cb',p,false);box(.062,.018,.008,x,y+.126,z+.077,color,p,false);}
 function pack(x,y,z,i,p,scale=1){const g=group('零食袋',x,y,z,p);g.scale.setScalar(scale);const c=candyColors[i%6];const m=box(.19,.27,.075,0,.135,0,c,g);m.rotation.z=Math.sin(i*2)*.06;box(.21,.025,.075,0,.271,0,P.cream,g,false);box(.21,.016,.075,0,.012,0,P.cream,g,false);box(.142,.118,.004,0,.16,.041,'#f7edca',g,false);ball(.044,.039,.006,0,.163,.046,c,g);}
 function biscuit(x,y,z,i,p){const a=cyl(.068,.068,.026,x,y,z,['#d6ad6a','#bc8c51','#ebcc91'][i%3],p,12);a.rotation.x=.13*(i%3);for(let k=0;k<3;k++)ball(.007,.004,.007,x+(k-1)*.028,y+.017,z,'#9f754b',p);}
 function jar(x,y,z,type,p,scale=1){const g=group('带盖糖果罐-'+type,x,y,z,p);g.scale.setScalar(scale);g.userData.kind='candy-jar';g.userData.contents=36;
  const points=[[.12,0],[.22,.025],[.28,.13],[.30,.31],[.285,.48],[.23,.58],[.20,.59],[.20,.66]].map(a=>new THREE.Vector2(...a));const shell=mesh(new THREE.LatheGeometry(points,32),glass,g);shell.name='透明蓝边鼓腹罐';
  ring(.2,.017,0,.65,0,'#6c9bad',g);ring(.205,.014,0,.59,0,'#6c9bad',g);ring(.222,.014,0,.03,0,'#6593a6',g);
  cyl(.22,.22,.012,0,.011,0,glass,g,32);for(let j=0;j<45;j++){const layer=Math.floor(j/9),a=(j%9)*Math.PI/4+layer*.36,r=j%9===8?0:.14,yy=.058+layer*(type===0?.079:.064),xx=Math.cos(a)*r,zz=Math.sin(a)*r;if(type===1){const m=cyl(.056,.056,.036,xx,yy,zz,'#d7b96c',g,12);m.rotation.z=.48+(j%3)*.06;}else if(type===2){const m=box(.095,.059,.12,xx,yy,zz,['#d69f58','#dbb875','#c18a49'][j%3],g,false);m.rotation.y=a;}else ball(.054,.043,.05,xx,yy,zz,candyColors[j%6],g);}g.userData.contents=45;
  cyl(.22,.23,.035,0,.682,0,'#c4ac6a',g,32);cyl(.18,.20,.028,0,.713,0,'#d6c186',g,32);beam([-.09,.738,0],[-.09,.79,0],.014,P.edge,g);beam([.09,.738,0],[.09,.79,0],.014,P.edge,g);beam([-.09,.79,0],[.09,.79,0],.016,'#b59b5e',g);
  // Thin blue silhouettes define glass without obscuring the colorful contents.
  w.tube([[-.21,.06,.08],[-.29,.22,.08],[-.27,.45,.07],[-.2,.59,.04]],.009,'#77a8ba',g);w.tube([[.21,.06,.08],[.29,.22,.08],[.27,.45,.07],[.2,.59,.04]],.009,'#77a8ba',g);batch(g);return g;
 }
 function clearBox(x,y,z,p,i=0){const g=group('透明方盒',x,y,z,p);g.userData.kind='clear-box';box(.40,.24,.30,0,.12,0,glass,g,false);for(const xx of [-.2,.2])for(const zz of [-.15,.15])box(.01,.24,.01,xx,.12,zz,'#90b3bb',g,false);box(.42,.025,.32,0,.25,0,'#b9c9bc',g);for(let k=0;k<8;k++)ball(.042,.03,.045,-.14+(k%4)*.09,.04+Math.floor(k/4)*.065,Math.sin(k*3)*.08,candyColors[(k+i)%6],g);batch(g);return g;}
 function openCylinder(x,y,z,p){const g=group('斜口圆筒罐',x,y,z,p);g.userData.kind='slanted-canister';const body=group('倾斜罐体',0,.22,0,g);body.rotation.x=.36;cyl(.14,.14,.36,0,0,0,glass,body,24);ring(.14,.017,0,.18,0,'#7aa1ac',body);cyl(.13,.13,.016,0,-.18,0,'#e4d8ae',body,24);for(let i=0;i<12;i++)box(.04,.18,.04,Math.cos(i*2.4)*.085,-.07,Math.sin(i*2.4)*.085,'#dfbb70',body,false);batch(g);return g;}
 function counter(x,z,p){const g=group('木质陈列台',x,.32,z,p);g.userData.kind='counter';g.userData.footprint={w:2.28,d:1.24};for(const xx of [-.94,.94])for(const zz of [-.46,.46])box(.12,.12,.12,xx,.06,zz,P.edge,g);box(2.12,.85,1.1,0,.545,0,P.wood,g);for(let i=0;i<14;i++)box(.012,.79,.012,-1+i*.154,.55,.556,'#997144',g,false);box(2.28,.1,1.24,0,1.02,0,P.lightWood,g);box(2.24,.035,.045,0,1.081,.6,'#dfbb84',g,false);box(2.11,.065,.04,0,.18,.565,P.edge,g);batch(g);return g;}
 function slopedDisplay(x,z,p){const g=group('三层斜面零食展示柜',x,.32,z,p);g.rotation.y=Math.PI;g.userData.kind='sloped-display';g.userData.levels=3;g.userData.footprint={w:1.92,d:.94};
  // Its front slopes from z=.5 at the base to z=-.23 at the top.
  box(1.92,.23,.94,0,.115,0,P.edge,g);box(1.92,1.43,.07,0,.875,-.43,P.wood,g);for(const xx of [-.94,.94]){const side=w.solid([[-.50,.2],[.43,.2],[.43,1.66],[.23,1.66]],.07,P.wood,g);side.rotation.y=Math.PI/2;side.position.set(xx-.035,0,0);}
  const ys=[.34,.76,1.18],fronts=[.4,.19,-.02];for(let level=0;level<3;level++){const y=ys[level],front=fronts[level],depth=front+.41;box(1.82,.05,depth,0,y,(front-.41)/2,P.lightWood,g);box(1.9,.055,.055,0,y+.07,front+.025,P.edge,g);for(let k=0;k<6;k++){if(level===0)pack(-.72+k*.28,y+.03,.02,k,g,.77);else if(level===1)for(let row=0;row<2;row++)biscuit(-.73+k*.29,y+.038,-.17+row*.14,k+row,g);else{box(.23,.14,.15,-.72+k*.28,y+.095,-.23,candyColors[(k+1)%6],g);box(.17,.045,.008,-.72+k*.28,y+.11,-.149,P.cream,g,false);}}}
  const topY=1.68,lowY=.22,topZ=-.23,lowZ=.50,length=Math.hypot(topY-lowY,topZ-lowZ);const glazing=box(1.84,length,.012,0,(topY+lowY)/2,(topZ+lowZ)/2,glass,g,false);glazing.rotation.x=Math.atan2(topZ-lowZ,topY-lowY);for(const xx of [-.92,.92])beam([xx,lowY,lowZ],[xx,topY,topZ],.035,P.edge,g);beam([-.95,topY,topZ],[.95,topY,topZ],.038,P.lightWood,g);for(let k=0;k<3;k++){const y=.43+k*.42,zz=lowZ+(y-lowY)/(topY-lowY)*(topZ-lowZ);ball(.04,.04,.026,.83,y,zz+.03,'#c9b477',g);}
  batch(g);return g;
 }
 function stool(x,z,color,p){const g=group('圆凳',x,.32,z,p);g.userData.kind='stool';g.userData.seatHeight=.61;for(let i=0;i<4;i++){const a=Math.PI/4+i*Math.PI/2;beam([Math.cos(a)*.21,.035,Math.sin(a)*.21],[Math.cos(a)*.14,.56,Math.sin(a)*.14],.025,'#8d8c80',g);cyl(.033,.035,.035,Math.cos(a)*.21,.018,Math.sin(a)*.21,'#575956',g,8);}ring(.19,.015,0,.23,0,'#9a998b',g);cyl(.275,.27,.095,0,.59,0,color,g,32);cyl(.24,.25,.025,0,.65,0,color,g,32);batch(g);return g;}
 function dessert(x,y,z,p,i=0){const g=group('条纹甜品杯与小勺',x,y,z,p);cyl(.11,.065,.18,0,.09,0,'#f4eada',g,24);for(let k=0;k<10;k++){const a=k*Math.PI/5;beam([Math.cos(a)*.067,.014,Math.sin(a)*.067],[Math.cos(a)*.108,.175,Math.sin(a)*.108],.008,i?'#c16965':'#5c83ac',g);}ring(.11,.009,0,.18,0,'#e8e4d2',g);for(let k=0;k<7;k++)ball(.045,.034,.045,Math.cos(k*2.4)*.052,.202,Math.sin(k*2.4)*.052,i?'#9abc83':'#d38491',g);beam([.19,.01,-.1],[.19,.01,.09],.01,'#d2d5c7',g);ball(.026,.009,.043,.19,.009,.12,'#d2d5c7',g);batch(g);return g;}
 function table(x,z,p){const g=group('靠墙窄长桌',x,.32,z,p);g.userData.kind='table';g.userData.footprint={w:.59,d:2.9};for(const xx of [-.19,.19])for(const zz of [-1.22,1.22])box(.055,.91,.055,xx,.455,zz,'#90836b',g);box(.57,.09,2.94,0,.96,0,'#ccb58e',g);box(.048,.16,2.7,-.23,.84,0,'#aa8d67',g);batch(g);dessert(0,1.005,.83,g);dessert(-.04,1.005,-.95,g,1);const holder=group('绿色插杆圆筒',0,1.005,-.1,g);cyl(.092,.082,.24,0,.12,0,'#59936a',holder,20);cyl(.073,.073,.012,0,.235,0,'#375d47',holder,20);for(let i=0;i<8;i++)beam([Math.sin(i*2.4)*.045,.12,Math.cos(i*2.4)*.045],[Math.sin(i*2.4)*.075,.37+(i%3)*.035,Math.cos(i*2.4)*.07],.011,'#e5cf8b',holder);batch(holder);return g;}
 function freezer(x,z,p){const g=group('门前低冰柜',x,.16,z,p);g.userData.kind='freezer';for(const xx of [-.7,.7])for(const zz of [-.32,.32])cyl(.055,.055,.1,xx,.05,zz,'#667269',g);box(1.72,.78,.88,0,.49,0,'#e1dfc1',g);box(1.76,.065,.92,0,.9,0,'#758e86',g);for(const xx of [-.42,.42]){box(.81,.045,.78,xx,.946,0,'#e8e5ce',g);box(.22,.032,.04,xx,.98,.18,'#707e71',g);}for(let k=0;k<5;k++)box(.22,.014,.006,.6,.26+k*.04,.445,'#78887c',g,false);face(.48,.21,-.4,.54,.448,label('freezer-ice','アイス','#f4ebce','#577c75'),g);batch(g);return g;}
 function productCard(text,x,y,z,p,i){const g=group('商品挂卡-'+i,x,y,z,p);box(.36,.38,.012,0,0,0,'#e6dcc6',g);face(.34,.36,0,0,.008,label('card-'+i,text,'#f3e6c5','#6e6853'),g);beam([0,.2,0],[0,.31,0],.008,'#827a60',g);batch(g);return g;}
 return {jar,clearBox,openCylinder,counter,slopedDisplay,stool,table,freezer,productCard,bottle,pack};
}
